"""Executable, hand-authored TRAIN fixtures for engineering workflows.

The four project families are reserved in their entirety for TRAIN. Each check
is an independent black-box example derived from the corresponding requirement.
"""
from __future__ import annotations

import json
import sys


def case(family, name, requirement, seed, done, partial, unrelated, checks, rationale):
    filename = name.replace('-', '_') + '.py'
    return {
        'family': 'engineering-' + family + '-v1', 'group': name,
        'requirement': f'In {filename}, ' + requirement,
        'seed_files': {filename: seed},
        'snapshots': {
            'DONE': {filename: done},
            'PARTIAL': {filename: partial},
            'NOT_STARTED': {filename: seed + '\n' + unrelated},
        },
        'rationale': rationale,
        'checks': [{'name': n, 'argv': [sys.executable, '-c', s.replace('$MODULE', filename[:-3])], 'files': {}} for n, s in checks],
    }


